with filtered as (select *, round(discount_pct, 2) as discount_pct_rounded, year(starts_on) as starts_on_year from promotions where starts_on > date '2023-12-16' and channel is not null) select case when discount_pct_rounded >= 78 then 'LARGE' else 'SMALL' end as discount_pct_rounded_tier, case when starts_on_year >= 69 then 'HIGH' else 'LOW' end as starts_on_year_tier, approx_percentile(discount_pct, array(0.25, 0.5, 0.75)) as discount_pct_quartiles, round(sum(discount_pct) / nullif(count(case when promo_code = 'SPRING10' then 1 end), 0), 2) as discount_pct_per_spring10, size(collect_set(promo_code)) as num_promo_codes from filtered group by discount_pct_rounded_tier, starts_on_year_tier order by discount_pct_per_spring10 desc
